var assets=UnityEditor.AssetDatabase.LoadAllAssetsAtPath("Assets/Vroid/Gardenerkawaii.vrm");return new{clothTextures=assets.OfType<UnityEngine.Material>().Where(m=>m.name.Contains("CLOTH")&&m.HasProperty("_ShadeTex")).Select(m=>new{name=m.name,sameLitShadeTexture=m.GetTexture("_MainTex")==m.GetTexture("_ShadeTex"),toony=m.HasProperty("_ShadingToonyFactor")?m.GetFloat("_ShadingToonyFactor"):-1}).ToArray(),expressions=assets.OfType<UniVRM10.VRM10Expression>().Select(e=>new{name=e.name,colorBindings=e.MaterialColorBindings.Length}).ToArray()};
